    <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><header class="flex flex-col justify-between gap-3 border-b border-slate-200 px-5 py-4 sm:flex-row sm:items-center"><div><h2 class="font-black text-slate-950">Copias de base de datos</h2><p class="mt-1 text-xs text-slate-500">Archivos privados cifrados con AES-256-GCM y verificación SHA-256.</p></div><span class="rounded-full bg-brand-50 px-3 py-1 text-xs font-black text-brand-800">Automático: {{ config('security.backups.run_at') }}</span></header><div class="overflow-x-auto"><table class="min-w-full divide-y divide-slate-200"><thead class="bg-slate-50"><tr><th class="px-5 py-3 text-left text-xs font-bold uppercase text-slate-500">Respaldo</th><th class="px-5 py-3 text-left text-xs font-bold uppercase text-slate-500">Estado</th><th class="px-5 py-3 text-left text-xs font-bold uppercase text-slate-500">Tamaño</th><th class="px-5 py-3 text-left text-xs font-bold uppercase text-slate-500">Creado por</th><th class="px-5 py-3 text-right text-xs font-bold uppercase text-slate-500">Acción</th></tr></thead><tbody class="divide-y divide-slate-100">@forelse($backups as $backup)<tr><td class="px-5 py-4"><p class="font-mono text-xs font-bold text-slate-900">{{ $backup->filename }}</p><p class="mt-1 text-xs text-slate-500">{{ $backup->started_at->format('d/m/Y H:i:s') }} · {{ strtoupper($backup->database_driver) }}</p>@if($backup->sha256)<p class="mt-1 max-w-sm truncate font-mono text-[10px] text-slate-400" title="{{ $backup->sha256 }}">SHA-256 {{ $backup->sha256 }}</p>@endif</td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-bold {{ $backup->status === 'completed' ? 'bg-emerald-50 text-emerald-700' : ($backup->status === 'failed' ? 'bg-red-50 text-red-700' : 'bg-amber-50 text-amber-700') }}">{{ $backup->status === 'completed' ? 'Completado' : ($backup->status === 'failed' ? 'Falló' : 'En proceso') }}</span>@if($backup->error_message)<p class="mt-2 max-w-xs text-xs text-red-700">{{ $backup->error_message }}</p>@endif</td><td class="px-5 py-4 text-sm font-bold text-slate-700">{{ $backup->size_bytes ? number_format($backup->size_bytes / 1048576, 2).' MB' : '—' }}</td><td class="px-5 py-4 text-sm text-slate-600">{{ $backup->creator?->name ?? 'Tarea automática' }}</td><td class="px-5 py-4 text-right">@if($backup->file_exists)<a href="{{ route('security.backups.download', $backup) }}" class="rounded-lg bg-slate-950 px-3 py-2 text-xs font-black text-white">Descargar</a>@else<span class="text-xs text-slate-400">No disponible</span>@endif</td></tr>@empty<tr><td colspan="5" class="px-5 py-12 text-center text-sm text-slate-500">Todavía no hay respaldos.</td></tr>@endforelse</tbody></table></div>@if($backups->hasPages())<div class="border-t border-slate-200 px-5 py-4">{{ $backups->links() }}</div>@endif</section>

    <section class="rounded-2xl border border-amber-200 bg-amber-50 p-5"><h2 class="font-black text-amber-950">Restauración segura por consola</h2><p class="mt-2 text-sm leading-6 text-amber-900">La restauración no está disponible desde el navegador para evitar reemplazos accidentales. El comando verifica SHA-256, crea una copia preventiva y activa mantenimiento.</p><code class="mt-3 block overflow-x-auto rounded-xl bg-slate-950 p-3 text-xs text-white">php artisan backup:restore ID --force --confirm="NOMBRE-EXACTO.bcbk"</code><p class="mt-2 text-xs font-semibold text-amber-800">Procedimiento completo: docs/RESPALDOS-Y-RESTAURACION.md</p></section>

    <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><header class="flex flex-col justify-between gap-3 border-b border-slate-200 px-5 py-4 sm:flex-row"><div><h2 class="font-black text-slate-950">Monitoreo de errores</h2><p class="mt-1 text-xs text-slate-500">Excepciones agrupadas por origen y recurrencia.</p></div><label class="flex items-center gap-2 text-sm font-bold text-slate-700"><input type="checkbox" wire:model.live="onlyOpenErrors" class="rounded border-slate-300 text-brand-600"> Solo pendientes</label></header><div class="divide-y divide-slate-100">@forelse($errors as $error)<article class="grid gap-4 px-5 py-4 lg:grid-cols-[1fr_auto]"><div><div class="flex flex-wrap items-center gap-2"><span class="rounded bg-red-50 px-2 py-1 text-xs font-black text-red-700">{{ $error->status_code ?? 500 }}</span><strong class="text-sm text-slate-950">{{ class_basename($error->exception_class) }}</strong><span class="text-xs text-slate-500">{{ $error->occurrences }} ocurrencia(s)</span></div><p class="mt-2 text-sm text-slate-700">{{ $error->message }}</p><p class="mt-1 text-xs text-slate-500">{{ $error->request_method }} /{{ $error->request_path }} · último {{ $error->last_occurred_at->diffForHumans() }}</p></div><div>@if(!$error->resolved_at)<button type="button" wire:click="resolveError({{ $error->id }})" class="rounded-lg border border-emerald-300 px-3 py-2 text-xs font-black text-emerald-700">Marcar resuelto</button>@else<span class="text-xs font-bold text-emerald-700">Resuelto</span>@endif</div></article>@empty<div class="px-5 py-10 text-center text-sm text-slate-500">No hay errores {{ $onlyOpenErrors ? 'pendientes' : 'registrados' }}.</div>@endforelse</div>@if($errors->hasPages())<div class="border-t border-slate-200 px-5 py-4">{{ $errors->links() }}</div>@endif</section>

